import math
from datetime import datetime


class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time.")

        total_seconds = (exit - entry).total_seconds()

        # Flat penalty of 200.00 for stays strictly greater than 24 hours (86400 seconds)
        if total_seconds > 24 * 3600:
            return 200.00

        # Calculate billed hours; every started hour counts as a full hour
        billed_hours = math.ceil(total_seconds / 3600)

        return round(billed_hours * self.hourly_rate, 2)
